// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 amount) public {
        vm.assume(target != address(0) && target != address(c) && target != address(this));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 balanceBefore = target.balance;
        vm.prank(c.owner());
        c.sendMoney(target, amount);
        uint256 balanceAfter = target.balance;
        assertTrue(balanceAfter == balanceBefore + amount);
    }
}
